(144, 1, '<div id="wrap_id_advice_486" >	<section id="0_cmscritics2014" class="panel " style="display:none">\r\n		<header class="panel-heading">\r\n			<span class="icon-lightbulb"></span> Tips of the day</header>\r\n		<div class="panel-body" style="padding:0">\r\n			<img class="img-responsive" src="https://api.prestashop.com/partner/tipsoftheday/img/logo-cmscritics2014.png" style="float:right; margin-left: 5px;">\r\n			<img src="https://gamification.prestashop.com/api/getAdviceImg/486.png"/>\r\n			<p><b>CMS Critic Awards 2014</b></p>\r\n			<p>Like PrestaShop? Please vote for us as the Best Ecommerce Solution in the CMS Critic awards</p>\r\n			<span class="text-right" style="float:right">\r\n				<a class="btn btn-default" target="_blank" href="http://gamification.prestashop.com/get_advice_link.php?id_advice=486&url=http%3A%2F%2Fawards.cmscritic.com%2Fvote">Vote now!</a>\r\n			</span>\r\n		</div>\r\n	</section>\r\n	<script>\r\n	$(document).ready( function () {\r\n		$(''#''+rand(0)+''_cmscritics2014'').show();\r\n	});\r\n	\r\n	function rand(nbr){\r\n	   return Math.floor(Math.random()*(nbr+1));\r\n	}\r\n	</script>\r\n	</div>'),
